INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2023/09/22 14:59:59", 1.47, -470, "2023/06/30 12:00:00", 1, 126401, 2, 1, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", "クローチェ", 2002, 1, 10001);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2023/09/22 14:59:59", 2.15, -470, "2023/06/30 12:00:00", 2, 126401, 1, 1, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", "クローチェ", 2002, 2, 10002);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2023/09/22 14:59:59", 0, -470, "2023/06/30 12:00:00", 1, 126501, 2, 1, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", "ライラエル", 2002, 2, 10003);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2023/09/22 14:59:59", 0, -470, "2023/06/30 12:00:00", 2, 126501, 1, 1, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", "ライラエル", 2002, 1, 10004);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2023/12/22 14:59:59", 0, -470, "2023/09/15 15:00:00", 1, 127702, 2, 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", "リンド", 2002, 2, 10005);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2023/12/22 14:59:59", 0, -470, "2023/09/15 15:00:00", 2, 127702, 2, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", "リンド", 2002, 2, 10006);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2023/12/22 14:59:59", 0, -470, "2023/09/15 15:00:00", 1, 127802, 1, 2, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", "ヴルム", 2002, 1, 10007);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2023/12/22 14:59:59", 6.5, -470, "2023/09/15 15:00:00", 2, 127802, 1, 2, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", "ヴルム", 2002, 2, 10008);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/03/22 14:59:59", 0, -470, "2023/12/15 15:00:00", 1, 129602, 1, 3, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", "アネモネ", 2002, 2, 10009);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/03/22 14:59:59", 0, -470, "2023/12/15 15:00:00", 2, 129602, 1, 3, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", "アネモネ", 2002, 2, 10010);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/03/22 14:59:59", 0, -470, "2023/12/15 15:00:00", 1, 129701, 1, 3, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", "ネフィ=ネラ", 2002, 1, 10011);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/03/22 14:59:59", 6.2, -470, "2023/12/15 15:00:00", 2, 129701, 1, 3, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", "ネフィ=ネラ", 2002, 2, 10012);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/06/22 14:59:59", 3.1, -470, "2024/03/15 15:00:00", 1, 130301, 5, 4, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", "カノン", 2002, 3, 10013);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/06/22 14:59:59", 6.15, -470, "2024/03/15 15:00:00", 2, 130301, 2, 4, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", "カノン", 2002, 3, 10014);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/06/22 14:59:59", 0, -470, "2024/03/15 15:00:00", 1, 130401, 2, 4, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", "ナーナ", 2002, 2, 10015);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/06/22 14:59:59", 3.35, -470, "2024/03/15 15:00:00", 2, 130401, 1, 4, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", "ナーナ", 2002, 2, 10016);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/09/22 14:59:59", 0, -470, "2024/06/15 15:00:00", 1, 130502, 1, 5, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", "ホウオウ", 2002, 1, 10017);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/09/22 14:59:59", 3.18, -470, "2024/06/15 15:00:00", 2, 130502, 1, 5, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", "ホウオウ", 2002, 2, 10018);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/09/22 14:59:59", 0, -470, "2024/06/15 15:00:00", 3, 130503, 4, 5, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", "ホウオウ", 2002, 4, 10019);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/09/22 14:59:59", 4.9, -470, "2024/06/15 15:00:00", 1, 123301, 2, 5, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", "ネア", 2002, 1, 10020);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/09/22 14:59:59", 4.8, -470, "2024/06/15 15:00:00", 2, 123301, 2, 5, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", "ネア", 2002, 1, 10021);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/12/22 14:59:59", 4.922, -470, "2024/09/15 15:00:00", 1, 133301, 1, 6, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", "カリザ", 2002, 3, 10022);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/12/22 14:59:59", 9.638, -470, "2024/09/15 15:00:00", 2, 133301, 5, 6, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", "カリザ", 2002, 3, 10023);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/12/22 14:59:59", 2.88, -470, "2024/09/15 15:00:00", 1, 133401, 2, 6, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", "ミーア", 2002, 1, 10024);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2024/12/22 14:59:59", 4.818, -470, "2024/09/15 15:00:00", 2, 133401, 1, 6, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", "ミーア", 2002, 5, 10025);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/03/22 14:59:59", 1.78, -470, "2024/12/15 15:00:00", 1, 133002, 1, 7, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", "グレイス", 2002, 2, 10026);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/03/22 14:59:59", 6.15, -470, "2024/12/15 15:00:00", 2, 133002, 7, 7, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", "グレイス", 2002, 1, 10027);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/03/22 14:59:59", 4.28, -470, "2024/12/15 15:00:00", 1, 133102, 2, 7, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", "ヴァイオレット", 2002, 6, 10028);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/03/22 14:59:59", 0, -470, "2024/12/15 15:00:00", 2, 133102, 1, 7, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", "ヴァイオレット", 2002, 1, 10029);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/06/23 14:59:59", 5.53, -470, "2025/03/15 15:00:00", 1, 136902, 1, 8, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", "ルルィ", 2002, 2, 10030);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/06/23 14:59:59", 6.05, -470, "2025/03/15 15:00:00", 2, 136902, 7, 8, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", "ルルィ", 2002, 9, 10031);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/06/23 14:59:59", 0, -470, "2025/03/15 15:00:00", 1, 137001, 1, 8, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", "デュラン", 2002, 2, 10032);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/06/23 14:59:59", 0, -470, "2025/03/15 15:00:00", 2, 137001, 1, 8, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", "デュラン", 2002, 2, 10033);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/09/23 14:59:59", 0, -470, "2025/06/16 15:00:00", 1, 135902, 2, 9, "おう\n好きなもん持ってきな", "サツキ", 2002, 2, 10034);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/09/23 14:59:59", 4.935, -470, "2025/06/16 15:00:00", 2, 135902, 6, 9, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", "サツキ", 2002, 1, 10035);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/09/23 14:59:59", 7.441, -470, "2025/06/16 15:00:00", 1, 135802, 5, 9, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", "ユキノ", 2002, 2, 10036);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/09/23 14:59:59", 0, -470, "2025/06/16 15:00:00", 2, 135802, 7, 9, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", "ユキノ", 2002, 7, 10037);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/12/22 14:59:59", 2.295, -470, "2025/09/16 15:00:00", 1, 130901, 2, 10, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", "クルル", 2002, 2, 10038);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/12/22 14:59:59", 6.281, -470, "2025/09/16 15:00:00", 2, 130901, 6, 10, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", "クルル", 2002, 1, 10039);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/12/22 14:59:59", 5.549, -470, "2025/09/16 15:00:00", 1, 137701, 1, 10, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", "ヴォルガーノ", 2002, 2, 10040);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2025/12/22 14:59:59", 2.64, -470, "2025/09/16 15:00:00", 2, 137701, 6, 10, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", "ヴォルガーノ", 2002, 3, 10041);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/03/23 11:59:59", 7.642, -470, "2025/12/15 15:00:00", 1, 132801, 4, 11, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", "ライラエル", 2002, 7, 10042);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/03/23 11:59:59", 0, -470, "2025/12/15 15:00:00", 2, 132802, 1, 11, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", "ライラエル", 2002, 1, 10043);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/03/23 11:59:59", 0, -470, "2025/12/15 15:00:00", 1, 134502, 1, 11, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", "クローチェ", 2002, 1, 10044);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/03/23 11:59:59", 3.72, -470, "2025/12/15 15:00:00", 2, 134501, 1, 11, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", "クローチェ", 2002, 2, 10045);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/06/22 11:59:59", 4.991, -470, "2026/03/16 12:00:00", 1, 138201, 1, 12, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", "ネフィ＝ネラ", 2002, 2, 10046);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/06/22 11:59:59", 3.877, -470, "2026/03/16 12:00:00", 2, 138201, 4, 12, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", "ネフィ＝ネラ", 2002, 1, 10047);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/06/22 11:59:59", 1.71, -470, "2026/03/16 12:00:00", 1, 136001, 6, 12, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", "アラクネ", 2002, 4, 10048);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/06/22 11:59:59", 5.32, -470, "2026/03/16 12:00:00", 2, 136001, 2, 12, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", "アラクネ", 2002, 5, 10049);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/09/22 11:59:59", 3.727, -470, "2026/06/15 12:00:00", 1, 135401, 4, 13, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", "アネモネ", 2002, 9, 10050);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/09/22 11:59:59", 7.213, -470, "2026/06/15 12:00:00", 2, 135401, 9, 13, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", "アネモネ", 2002, 7, 10051);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/09/22 11:59:59", 1.874, -470, "2026/06/15 12:00:00", 1, 135301, 2, 13, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", "クリア", 2002, 1, 10052);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/09/22 11:59:59", 0, -470, "2026/06/15 12:00:00", 2, 135301, 2, 13, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", "クリア", 2002, 2, 10053);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/12/22 11:59:59", 4.215, -470, "2026/09/15 12:00:00", 1, 138001, 1, 14, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", "ヴァイオレット", 2002, 2, 10054);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/12/22 11:59:59", 0, -470, "2026/09/15 12:00:00", 2, 138001, 4, 14, "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", "ヴァイオレット", 2002, 4, 10055);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/12/22 11:59:59", 5.477, -470, "2026/09/15 12:00:00", 1, 138901, 1, 14, "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", "グレイス", 2002, 6, 10056);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "2026/12/22 11:59:59", 5.743, -470, "2026/09/15 12:00:00", 2, 138901, 1, 14, "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", "グレイス", 2002, 2, 10057);
